/* Change Database Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Android Cupcake": "Android 1.5's dessert codename, starting the sweet tradition.", "Ubuntu Breezy Badger": "Ubuntu 5.10's alliterative animal: breezy badger.", "macOS Big Sur": "macOS 11's California landmark name.", "Windows XP": "experience — Microsoft", "Debian Buzz": "Debian 1.1's Toy Story character codename.", "Linux 6.x": "The Linux kernel's plain numeric versions: change named by number.", "LTS": "The surname of stable releases: long-term support.", "Service Pack": "The bundled-update surname of Windows eras.", "Point release": "The x.y.z surname: minor change, major meaning.", "Beta / RC": "The pre-release surnames: beta, then release candidate."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Android Cupcake';
console.log(lookup(q));

